1	import { NextRequest, NextResponse } from "next/server";
2	import { createHash, randomUUID } from "node:crypto";
3	import { EncryptJWT } from "jose";
4	import { db } from "@/lib/db";
5	import { currentUser } from "@/lib/auth";
6	import { pve, node as primaryNode } from "@/lib/proxmox";
7	
8	export const dynamic = "force-dynamic";
9	
10	/**
11	 * In-browser VNC console — ticket issuer.
12	 *
13	 * GET /api/console/[serverId]
14	 *
15	 * Flow:
16	 *  1. Authenticate the caller (owner or admin).
17	 *  2. Ask Proxmox for a websocket VNC proxy ticket for the server's VM
18	 *     (POST .../vncproxy?websocket=1). This returns a short-lived VNC ticket +
19	 *     an ephemeral port on the Proxmox node.
20	 *  3. Package the connection target — Proxmox API base, node, vmid, port, the
21	 *     VNC ticket, and the API token needed to authenticate the websocket
22	 *     upgrade — into an ENCRYPTED (JWE / A256GCM) token, valid 60s, with a
23	 *     unique jti so the relay can enforce single use.
24	 *  4. Return only { wsPath, ticketId } to the browser. The browser NEVER sees
25	 *     the Proxmox API token or the raw VNC ticket — those live inside the JWE,
26	 *     which only the relay (sharing AUTH_SECRET) can decrypt.
27	 *
28	 * The relay (scripts/console-proxy.mjs) receives sid=<JWE> on the browser
29	 * websocket, decrypts it, opens a TLS websocket to Proxmox with the real
30	 * credentials, and pipes bytes both ways.
31	 */
32	
33	// 256-bit symmetric key for JWE, derived from the app's AUTH_SECRET.
34	// The relay derives the identical key the same way — no extra shared secret.
35	function consoleKey(): Uint8Array {
36	  const secret = process.env.AUTH_SECRET;
37	  if (!secret) throw new Error("AUTH_SECRET is not set");
38	  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
39	}
40	
41	export async function GET(
42	  _req: NextRequest,
43	  { params }: { params: Promise<{ serverId: string }> }
44	) {
45	  const { serverId } = await params;
46	
47	  const user = await currentUser();
48	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
49	
50	  const server = await db.server.findUnique({
51	    where: { id: serverId },
52	    include: { node: true },
53	  });
54	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
55	    return NextResponse.json({ error: "not found" }, { status: 404 });
56	  }
57	  if (!server.vmid) {
58	    return NextResponse.json({ error: "no VM provisioned" }, { status: 409 });
59	  }
60	  if (server.status !== "RUNNING") {
61	    return NextResponse.json(
62	      { error: "server must be running to open the console" },
63	      { status: 409 }
64	    );
65	  }
66	
67	  // Resolve which Proxmox node + credentials to use. Multi-node servers carry a
68	  // Node row; otherwise fall back to the primary node from the environment.
69	  const apiBase = server.node?.apiUrl ?? process.env.PROXMOX_API_URL ?? "https://127.0.0.1:8006";
70	  const pveNode = server.node?.pveNode ?? primaryNode;
71	  const tokenId = server.node?.tokenId ?? process.env.PROXMOX_TOKEN_ID ?? "";
72	  const tokenSecret = server.node?.tokenSecret ?? process.env.PROXMOX_TOKEN_SECRET ?? "";
73	
74	  if (!pveNode || !tokenId || !tokenSecret) {
75	    return NextResponse.json({ error: "console not configured" }, { status: 500 });
76	  }
77	
78	  // Request a websocket VNC proxy ticket from Proxmox.
79	  let vnc: { ticket: string; port: string | number };
80	  try {
81	    // Use the node-scoped client for non-primary nodes so the ticket is valid
82	    // for the right host; the primary node uses the shared `pve` client.
83	    if (server.node) {
84	      const { pveFor } = await import("@/lib/proxmox");
85	      const client = pveFor({
86	        apiUrl: server.node.apiUrl,
87	        pveNode: server.node.pveNode,
88	        tokenId: server.node.tokenId,
89	        tokenSecret: server.node.tokenSecret,
90	      });
91	      vnc = await client.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
92	        websocket: 1,
93	      });
94	    } else {
95	      vnc = await pve.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
96	        websocket: 1,
97	      });
98	    }
99	  } catch {
100	    return NextResponse.json(
101	      { error: "hypervisor did not grant a console ticket — try again shortly" },
102	      { status: 502 }
103	    );
104	  }
105	
106	  if (!vnc?.ticket || vnc.port === undefined) {
107	    return NextResponse.json({ error: "invalid console ticket from hypervisor" }, { status: 502 });
108	  }
109	
110	  const ticketId = randomUUID();
111	
112	  // Encrypt the full connection target. Only the relay can read this.
113	  const sid = await new EncryptJWT({
114	    apiBase,
115	    node: pveNode,
116	    vmid: server.vmid,
117	    port: Number(vnc.port),
118	    vncticket: vnc.ticket,
119	    tokenId,
120	    tokenSecret,
121	  })
122	    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
123	    .setJti(ticketId)
124	    .setIssuedAt()
125	    .setExpirationTime("60s")
126	    .encrypt(consoleKey());
127	
128	  // Public websocket URL of the relay. In production behind HTTPS, set
129	  // CONSOLE_PUBLIC_WS_URL to a wss:// endpoint (e.g. proxied by nginx) so the
130	  // browser isn't blocked by mixed-content. Otherwise we hand out a bare
131	  // ws://PUBLIC_IP:PORT/console URL for the standalone relay.
132	  const base =
133	    process.env.CONSOLE_PUBLIC_WS_URL?.replace(/\/+$/, "") ??
134	    `ws://${process.env.PUBLIC_IP ?? "127.0.0.1"}:${process.env.CONSOLE_PROXY_PORT ?? "8899"}/console`;
135	
136	  const wsPath = `${base}?sid=${encodeURIComponent(sid)}`;
137	
138	  return NextResponse.json({ wsPath, ticketId });
139	}
140

1	import { NextRequest, NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { vmRrd, nodeRrd } from "@/lib/proxmox";
5	
6	export async function GET(req: NextRequest) {
7	  const user = await currentUser();
8	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
9	
10	  const timeframe = ["hour", "day", "week", "month"].includes(req.nextUrl.searchParams.get("tf") ?? "")
11	    ? req.nextUrl.searchParams.get("tf")!
12	    : "hour";
13	
14	  const serverId = req.nextUrl.searchParams.get("serverId");
15	  try {
16	    if (serverId) {
17	      const server = await db.server.findUnique({ where: { id: serverId } });
18	      if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
19	        return NextResponse.json({ error: "not found" }, { status: 404 });
20	      }
21	      const data = await vmRrd(server.vmid, timeframe);
22	      return NextResponse.json({ data });
23	    }
24	    if (user.role !== "ADMIN") return NextResponse.json({ error: "forbidden" }, { status: 403 });
25	    const data = await nodeRrd(timeframe);
26	    return NextResponse.json({ data });
27	  } catch {
28	    return NextResponse.json({ data: [] });
29	  }
30	}
