1	import { NextResponse } from "next/server";
2	import { getHealth, type HealthReport } from "@/lib/monitoring";
3	
4	export const dynamic = "force-dynamic";
5	export const runtime = "nodejs";
6	
7	/**
8	 * GET /api/health — public, unauthenticated health probe.
9	 *
10	 * Returns { web, db, worker, proxmox } where each is
11	 * { status: "operational" | "degraded" | "down", detail }. Safe to expose:
12	 * no secrets, no per-customer data — just component states.
13	 *
14	 * Cached ~15s in-process so external monitors / the status page don't hammer
15	 * the DB and Proxmox on every request.
16	 */
17	
18	const TTL_MS = 15_000;
19	let cache: { at: number; body: HealthReport } | null = null;
20	
21	export async function GET() {
22	  try {
23	    if (!cache || Date.now() - cache.at > TTL_MS) {
24	      cache = { at: Date.now(), body: await getHealth() };
25	    }
26	    const worstDown =
27	      cache.body.db.status === "down" || cache.body.proxmox.status === "down";
28	    return NextResponse.json(cache.body, {
29	      status: worstDown ? 503 : 200,
30	      headers: { "Cache-Control": "public, max-age=15, s-maxage=15" },
31	    });
32	  } catch (e: any) {
33	    return NextResponse.json(
34	      { error: "health check failed", detail: String(e?.message ?? e).slice(0, 160) },
35	      { status: 500 }
36	    );
37	  }
38	}
