7	/**
8	 * RBAC-checked CSV export of the current (filtered) admin table.
9	 *
10	 *   /api/admin/export?type=users&q=…
11	 *   /api/admin/export?type=invoices&status=OPEN
12	 *
13	 * The filter params mirror the corresponding admin page so "Export CSV" always
14	 * reflects what the operator is looking at. Exports the full filtered set (not
15	 * just the current page). Never cached.
16	 */
17	export const dynamic = "force-dynamic";
18	
19	function csvCell(v: unknown): string {
20	  const s = v == null ? "" : String(v);
21	  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
22	}
23	
24	function toCsv(headers: string[], rows: (string | number | null | undefined)[][]): string {
25	  const lines = [headers.map(csvCell).join(",")];
26	  for (const row of rows) lines.push(row.map(csvCell).join(","));
27	  return lines.join("\r\n");
28	}
29	
30	function money(cents: number): string {
31	  return (cents / 100).toFixed(2);
32	}
33	
34	const INVOICE_STATUSES: InvoiceStatus[] = ["OPEN", "PAID", "VOID", "REFUNDED"];
35	
36	export async function GET(req: NextRequest) {
37	  const user = await realUser();
38	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
39	
40	  const sp = req.nextUrl.searchParams;
41	  const type = sp.get("type");
42	  const stamp = new Date().toISOString().slice(0, 10);
43	
44	  if (type === "users") {
45	    if (!canAccess(user.role, "clients")) {
46	      return NextResponse.json({ error: "forbidden" }, { status: 403 });
47	    }
48	    const query = (sp.get("q") ?? "").trim();
49	    const where: Prisma.UserWhereInput = query
50	      ? {
51	          OR: [
52	            { email: { contains: query, mode: "insensitive" } },
53	            { name: { contains: query, mode: "insensitive" } },
54	          ],
55	        }
56	      : {};
57	
58	    const users = await db.user.findMany({
59	      where,
60	      include: {
61	        servers: {
62	          where: { status: { notIn: ["DELETING"] } },
63	          select: { isFree: true, plan: { select: { priceCents: true } } },
64	        },
65	      },
66	      orderBy: { createdAt: "desc" },
67	    });
68	
69	    const csv = toCsv(
70	      ["id", "name", "email", "role", "balance_usd", "mrr_usd", "servers", "suspended", "joined"],
71	      users.map((u) => {
72	        const mrr = u.servers.reduce((n, s) => n + (s.isFree ? 0 : s.plan.priceCents), 0);
73	        return [
74	          u.id,
75	          u.name,
76	          u.email,
77	          u.role,
78	          money(u.balanceCents),
79	          money(mrr),
80	          u.servers.length,
81	          u.suspended ? "yes" : "no",
82	          u.createdAt.toISOString(),
83	        ];
84	      })
85	    );
86	
87	    return new NextResponse(csv, {
88	      status: 200,
89	      headers: {
90	        "Content-Type": "text/csv; charset=utf-8",
91	        "Content-Disposition": `attachment; filename="nxeon-clients-${stamp}.csv"`,
92	        "Cache-Control": "private, no-store",
93	      },
94	    });
95	  }
96	
97	  if (type === "invoices") {
98	    if (!canAccess(user.role, "billing")) {
99	      return NextResponse.json({ error: "forbidden" }, { status: 403 });
100	    }
101	    const statusParam = sp.get("status");
102	    const status = INVOICE_STATUSES.includes(statusParam as InvoiceStatus)
103	      ? (statusParam as InvoiceStatus)
104	      : undefined;
105	
106	    const invoices = await db.invoice.findMany({
107	      where: status ? { status } : {},
108	      include: { user: { select: { email: true, name: true } } },
109	      orderBy: { createdAt: "desc" },
110	    });
111	
112	    const csv = toCsv(
113	      ["number", "client_name", "client_email", "status", "description", "amount_usd", "tax_usd", "issued", "paid_at"],
114	      invoices.map((inv) => [
115	        String(inv.number).padStart(5, "0"),
116	        inv.user.name,
117	        inv.user.email,
118	        inv.status,
119	        inv.description,
120	        money(inv.amountCents),
121	        money(inv.taxCents),
122	        inv.createdAt.toISOString(),
123	        inv.paidAt ? inv.paidAt.toISOString() : "",
124	      ])
125	    );
126	
127	    return new NextResponse(csv, {
128	      status: 200,
129	      headers: {
130	        "Content-Type": "text/csv; charset=utf-8",
131	        "Content-Disposition": `attachment; filename="nxeon-invoices-${stamp}.csv"`,
132	        "Cache-Control": "private, no-store",
133	      },
134	    });
135	  }
136	
137	  return NextResponse.json({ error: "unknown export type; use ?type=users|invoices" }, { status: 400 });
138	}
