1	import { NextRequest, NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import { registrarConfigured, listRecords } from "@/lib/registrar";
5	
6	/**
7	 * Downloads the domain's current DNS records as a CSV / zone-style text file.
8	 * The format round-trips through the "Import DNS" paste box:
9	 *   name,type,value,ttl,priority
10	 * Comment lines (starting with #) are ignored by the importer.
11	 *
12	 * Ownership-checked: the caller must own the domain (or be an admin).
13	 */
14	export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
15	  const { id } = await params;
16	  const user = await currentUser();
17	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
18	
19	  const domain = await db.domain.findUnique({ where: { id } });
20	  if (!domain) return NextResponse.json({ error: "not found" }, { status: 404 });
21	  if (domain.userId !== user.id && user.role !== "ADMIN") {
22	    return NextResponse.json({ error: "forbidden" }, { status: 403 });
23	  }
24	
25	  if (domain.status !== "ACTIVE" || !registrarConfigured()) {
26	    return NextResponse.json(
27	      { error: "DNS export is available once the domain is active and the registrar is connected." },
28	      { status: 409 }
29	    );
30	  }
31	
32	  let records;
33	  try {
34	    records = await listRecords(domain.name);
35	  } catch (e) {
36	    return NextResponse.json(
37	      { error: `Could not read DNS records: ${String(e instanceof Error ? e.message : e).slice(0, 200)}` },
38	      { status: 502 }
39	    );
40	  }
41	
42	  const esc = (v: string) => (/[",\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);
43	  const lines: string[] = [
44	    `# DNS export for ${domain.name}`,
45	    `# Generated ${new Date().toISOString()} by Nxeon`,
46	    `# Format: name,type,value,ttl,priority   (import via the domain's "Import DNS" box)`,
47	    `name,type,value,ttl,priority`,
48	  ];
49	  for (const r of records) {
50	    const name = r.host === "" ? "@" : r.host;
51	    const priority = r.type === "MX" || r.type === "SRV" ? String(r.priority ?? "") : "";
52	    lines.push([esc(name), r.type, esc(r.answer), String(r.ttl ?? 300), priority].join(","));
53	  }
54	
55	  const body = lines.join("\n") + "\n";
56	  return new NextResponse(body, {
57	    status: 200,
58	    headers: {
59	      "Content-Type": "text/csv; charset=utf-8",
60	      "Content-Disposition": `attachment; filename="${domain.name}-dns.csv"`,
61	      "Cache-Control": "private, no-store",
62	    },
63	  });
64	}
