import { db } from "./db";
import { pve, node as primaryNode, pveFor } from "./proxmox";
import type { Node } from "@prisma/client";

/**
 * Shared, READ-ONLY monitoring helpers for Nxeon.
 *
 * Everything here is safe to call from server components (status page, admin
 * monitoring) and from the worker sweep (`worker/monitor.ts`). No mutations,
 * no secrets in the returned shapes — the public /status page renders off the
 * same `getHealth()` logic the API exposes.
 *
 * Proxmox access is strictly read-only: `GET /nodes/{node}/status` and
 * `GET /nodes/{node}/storage/{storage}/status` (+ backup content listing).
 */

export type CompStatus = "operational" | "degraded" | "down";
export type Component = { status: CompStatus; detail: string };

export type HealthReport = {
  web: Component;
  db: Component;
  worker: Component;
  proxmox: Component;
  checkedAt: string;
};

// ---- Thresholds (env-overridable) ---------------------------------------

/** Worker is expected to touch the queue within this window; older QUEUED work ⇒ down. */
export const WORKER_STALE_MS = Number(process.env.NXEON_WORKER_STALE_MS ?? 2 * 60_000);
/** A Job sitting in RUNNING longer than this is considered stuck. */
export const STUCK_JOB_MS = Number(process.env.NXEON_STUCK_JOB_MS ?? 15 * 60_000);
/** Storage usage above this fraction trips a disk-capacity alert. */
export const DISK_WARN_RATIO = Number(process.env.NXEON_DISK_WARN_RATIO ?? 0.85);
/** Node RAM usage above this fraction trips an alert. */
export const RAM_WARN_RATIO = Number(process.env.NXEON_RAM_WARN_RATIO ?? 0.9);
/** No fresh backup within this window ⇒ backups look stale. */
export const BACKUP_STALE_MS = Number(process.env.NXEON_BACKUP_STALE_MS ?? 48 * 60 * 60_000);
/** QUEUED backlog at/above this depth trips an alert. */
export const QUEUE_BACKLOG_ALERT = Number(process.env.NXEON_QUEUE_BACKLOG_ALERT ?? 25);

// ---- Small formatters ----------------------------------------------------

/** Compact human age from a millisecond duration. */
export function fmtAge(ms: number): string {
  if (ms < 0) ms = 0;
  const m = Math.floor(ms / 60_000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h`;
  const d = Math.floor(h / 24);
  return `${d}d ${h % 24}h`;
}

// ---- Proxmox targets (read-only) ----------------------------------------

type PveTarget = {
  label: string;
  pveNode: string;
  get: (path: string, params?: Record<string, any>) => Promise<any>;
  /** Distinct storages worth watching on this node. */
  storages: string[];
};

/**
 * Resolve the set of Proxmox nodes to poll. Prefers explicit `Node` rows
 * (multi-node), and falls back to the env-configured primary when none exist.
 */
export async function nodeTargets(): Promise<PveTarget[]> {
  const nodes = await db.node.findMany({
    where: { enabled: true },
    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
  });
  if (nodes.length === 0) {
    return [
      {
        label: primaryNode || "primary",
        pveNode: primaryNode,
        get: (p, pp) => pve.get(p, pp),
        storages: ["vmdata", "backup"],
      },
    ];
  }
  return nodes.map((n: Node) => {
    const client = pveFor({
      apiUrl: n.apiUrl,
      pveNode: n.pveNode,
      tokenId: n.tokenId,
      tokenSecret: n.tokenSecret,
    });
    const storages = [n.storageNvme, n.storageHdd, "backup"].filter(
      (v, i, a) => v && a.indexOf(v) === i
    );
    return { label: n.name, pveNode: n.pveNode, get: client.get, storages };
  });
}

export type StorageUsage = {
  node: string;
  storage: string;
  total: number;
  used: number;
  avail: number;
  ratio: number;
  reachable: boolean;
};

/** Per-node, per-storage disk usage (bytes). Unreachable storages are marked. */
export async function nodeStorageUsage(): Promise<StorageUsage[]> {
  const targets = await nodeTargets();
  const out: StorageUsage[] = [];
  for (const t of targets) {
    for (const storage of t.storages) {
      try {
        const st = await t.get(`/nodes/${t.pveNode}/storage/${storage}/status`);
        const total = Number(st?.total ?? 0);
        const used = Number(st?.used ?? 0);
        const avail = Number(st?.avail ?? Math.max(0, total - used));
        out.push({
          node: t.label,
          storage,
          total,
          used,
          avail,
          ratio: total > 0 ? used / total : 0,
          reachable: true,
        });
      } catch {
        out.push({ node: t.label, storage, total: 0, used: 0, avail: 0, ratio: 0, reachable: false });
      }
    }
  }
  return out;
}

