  if (clean.length < MIN_PROMPT_CHARS) {
    return { error: "Please describe what you'd like Claude to build (a sentence or two)." };
  }
  if (clean.length > MAX_PROMPT_CHARS) {
    return { error: `Prompt is too long (max ${MAX_PROMPT_CHARS} characters).` };
  }

  // BYOK gate: the owner must have an effective key (their own, or a platform fallback).
  const owner = await db.user.findUnique({
    where: { id: user.id },
    select: { anthropicKeyEnc: true },
  });
  if (!effectiveKeyFor(owner)) {
